import { headers } from "next/headers";

import { auth } from "@/lib/auth";
import { db } from "@/lib/db";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// Row shape of Better Auth's own "user" table (see src/lib/auth.ts) — this
// file is the read side of that table for the rest of the app, so sign-ups
// (email/password or Google) show up here with no extra syncing step.
type UserRow = {
  id: string;
  email: string;
  name: string;
  createdAt: string | number;
};

function toUser(row: UserRow): User {
  return {
    id: row.id,
    email: row.email,
    name: row.name,
    createdAt: new Date(row.createdAt).toISOString().slice(0, 10),
  };
}

export async function listUsers(): Promise<User[]> {
  const rows = db
    .prepare<[], UserRow>(
      `SELECT id, email, name, createdAt FROM user ORDER BY createdAt ASC`,
    )
    .all();
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = db
    .prepare<
      [string],
      UserRow
    >(`SELECT id, email, name, createdAt FROM user WHERE id = ?`)
    .get(id);
  return row ? toUser(row) : undefined;
}

// Real session handling: reads the Better Auth session cookie for the
// current request and resolves it to a signed-in user, or undefined.
export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session?.user) return undefined;

  return {
    id: session.user.id,
    email: session.user.email,
    name: session.user.name,
    createdAt: new Date(session.user.createdAt).toISOString().slice(0, 10),
  };
}

