"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";

import { authClient } from "@/lib/auth-client";

export default function SignUpPage() {
  const router = useRouter();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setPending(true);

    await authClient.signUp.email(
      { email, password, name, callbackURL: "/dashboard" },
      {
        onSuccess: () => {
          router.push("/dashboard");
          router.refresh();
        },
        onError: (ctx) => {
          setError(ctx.error.message ?? "Could not create your account.");
          setPending(false);
        },
      },
    );
  }

  return (
    <main className="mx-auto flex w-full max-w-sm flex-1 flex-col justify-center p-8">
      <h1 className="text-2xl font-semibold">Create your account</h1>
      <p className="mt-1 text-sm opacity-70">Get started with Notely.</p>

      <button
        type="button"
        disabled={pending}
        onClick={() => {
          setPending(true);
          void authClient.signIn.social({
            provider: "google",
            callbackURL: "/dashboard",
          });
        }}
        className="mt-6 flex h-11 w-full items-center justify-center gap-2 rounded-full border border-solid border-black/[.08] px-5 text-sm font-medium transition-colors hover:bg-black/[.04] disabled:opacity-50 dark:border-white/[.145] dark:hover:bg-[#1a1a1a]"
      >
        Continue with Google
      </button>

      <div className="mt-6 flex items-center gap-3 text-xs uppercase opacity-50">
        <div className="h-px flex-1 bg-current opacity-20" />
        or
        <div className="h-px flex-1 bg-current opacity-20" />
      </div>

      <form onSubmit={onSubmit} className="mt-6 flex flex-col gap-4">
        <label className="flex flex-col gap-1 text-sm">
          Name
          <input
            type="text"
            required
            autoComplete="name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="h-11 rounded-lg border border-solid border-black/[.08] bg-transparent px-3 outline-none focus:border-black/30 dark:border-white/[.145] dark:focus:border-white/40"
          />
        </label>
        <label className="flex flex-col gap-1 text-sm">
          Email
          <input
            type="email"
            required
            autoComplete="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="h-11 rounded-lg border border-solid border-black/[.08] bg-transparent px-3 outline-none focus:border-black/30 dark:border-white/[.145] dark:focus:border-white/40"
          />
        </label>
        <label className="flex flex-col gap-1 text-sm">
          Password
          <input
            type="password"
            required
            minLength={8}
            autoComplete="new-password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="h-11 rounded-lg border border-solid border-black/[.08] bg-transparent px-3 outline-none focus:border-black/30 dark:border-white/[.145] dark:focus:border-white/40"
          />
        </label>

        {error && <p className="text-sm text-red-600 dark:text-red-400">{error}</p>}

        <button
          type="submit"
          disabled={pending}
          className="mt-2 flex h-11 w-full items-center justify-center rounded-full bg-foreground text-sm font-medium text-background transition-colors hover:bg-[#383838] disabled:opacity-50 dark:hover:bg-[#ccc]"
        >
          {pending ? "Creating account…" : "Create account"}
        </button>
      </form>

      <p className="mt-6 text-sm opacity-70">
        Already have an account?{" "}
        <Link href="/sign-in" className="font-medium underline underline-offset-4">
          Sign in
        </Link>
      </p>
    </main>
  );
}

